REPLACE INTO rvs_project_page (project_page_id, rvs_usr_id, page_name, custom_page_name, rvs_component_id, page_data, head, page_title, meta_keyword, meta_description, effect_page_enter, duration_page_enter, meta_page_effect, rvs_link_id, target, form_template_id, i_pathway, i_mail, i_print, i_favorite, last_modifier) VALUES ('ac23fc44aeab78dc95b27a329e2cdbbb', '07f0292ce90de23b787e3ad6be4c6770', 'Career', '', '0', '<table class=\"rvFrame\" cellspacing=\"1\" cellpadding=\"1\" width=\"780\">\r\n<tbody>\r\n<tr>\r\n<td class=\"tdSolid\" valign=\"top\"></td></tr></tbody></table>\r\n<p>HingePoint Consulting always looks for top talents. We want exceptional people with outstanding capabilities and great problem solving, communication, tamwork and leadership skills.</p>\r\n<p>If you are interested, please send your resume to <u><font color=\"#0000ff\">career@hingepointconsulting.com</u></font>.</p>', '', '', '', '', null, null, '', '', '', '', null, null, null, null, '1258339463');
REPLACE INTO rvs_project_page (project_page_id, rvs_usr_id, page_name, custom_page_name, rvs_component_id, page_data, head, page_title, meta_keyword, meta_description, effect_page_enter, duration_page_enter, meta_page_effect, rvs_link_id, target, form_template_id, i_pathway, i_mail, i_print, i_favorite, last_modifier) VALUES ('8d94f612dd638dc2b712b62fed7c28bf', '07f0292ce90de23b787e3ad6be4c6770', 'Services', '', '0', '', '', '', '', '', null, null, '', '', '', '', null, null, null, null, null);
REPLACE INTO rvs_project_page (project_page_id, rvs_usr_id, page_name, custom_page_name, rvs_component_id, page_data, head, page_title, meta_keyword, meta_description, effect_page_enter, duration_page_enter, meta_page_effect, rvs_link_id, target, form_template_id, i_pathway, i_mail, i_print, i_favorite, last_modifier) VALUES ('1ca6bb939daa06a38e6d1ea234d24479', '07f0292ce90de23b787e3ad6be4c6770', 'About us', '', '0', '', '', '', '', '', null, null, '', '', '', '', null, null, null, null, null);
REPLACE INTO rvs_project_page (project_page_id, rvs_usr_id, page_name, custom_page_name, rvs_component_id, page_data, head, page_title, meta_keyword, meta_description, effect_page_enter, duration_page_enter, meta_page_effect, rvs_link_id, target, form_template_id, i_pathway, i_mail, i_print, i_favorite, last_modifier) VALUES ('47fc8ed0835236c3ca845b1c9dc72b87', '07f0292ce90de23b787e3ad6be4c6770', 'Corporate Development', '', '0', '<table id=\"rv_template_layout\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody>\r\n<tr>\r\n<td valign=\"top\" align=\"left\"></td></tr></tbody></table>\r\n<p>When it comes to strategic business decisions, no simple answers! Any strategy has to be assessed carefully given your enterprise&#8217;s special needs, market conditions, competition landscapes and global investment environments.</p>\r\n<p>In the scope of international business development, foreign direct investment, outsourcing, joint venture, strategic alliance, merger &amp; acquisition, ownership interests&#8230;, which one is the best for your business when it comes to international business development? Again, no one will fit all. </p>\r\n<p>We will work together with you to analyze your needs, study the market, assess the situations, evaluate various approaches and pave the road to your success.</p>', '', '', '', '', null, null, '', '', '', '', null, null, null, null, '1258340045');
REPLACE INTO rvs_project_page (project_page_id, rvs_usr_id, page_name, custom_page_name, rvs_component_id, page_data, head, page_title, meta_keyword, meta_description, effect_page_enter, duration_page_enter, meta_page_effect, rvs_link_id, target, form_template_id, i_pathway, i_mail, i_print, i_favorite, last_modifier) VALUES ('6f4a0de836f3b7b3c32ad7dbdba05b43', '07f0292ce90de23b787e3ad6be4c6770', 'Home', '', '0', '<table class=\"rvFrame\" cellspacing=\"1\" cellpadding=\"1\" width=\"90%\">\r\n<tbody>\r\n<tr>\r\n<td width=\"10%\"></td>\r\n<td class=\"tdSolid\" valign=\"top\" align=\"left\">\r\n<div align=\"center\"><font size=\"4\">Welcome to HingePoint Consulting&nbsp;&nbsp;</font></div></td></tr></tbody></table>\r\n<p>Looking into the multicultural Chinese market here in Canada, or want to build up business relationships with China, one of the fastest growing market? </p>\r\n<p>Established in China, want to expand your business into international market and enter into global capital markets, especially Canada, whose financial system won great credits during the past global financial crisis? </p>\r\n<p>Come with us&#8230;</p>\r\n<p>Aiming to help businesses to grow in and between Canada and China, two of the greatest countries of the world, HingePoint Consulting provides corporate development, communications and client relations consulting service to all type of clients, from multibillion public companies to small capital start ups.</p>\r\n<p align=\"justify\"></p>\r\n<p align=\"justify\">Creative in problem solving, innovative in leading changes, HingePoint brings you not only feasible business strategies, but also tangible business results. </p></td>\r\n<td width=\"10%\"></td></tr></tbody></table>', '', '', '', '', null, null, '', '', '', '', null, null, null, null, '1258341300');
REPLACE INTO rvs_project_page (project_page_id, rvs_usr_id, page_name, custom_page_name, rvs_component_id, page_data, head, page_title, meta_keyword, meta_description, effect_page_enter, duration_page_enter, meta_page_effect, rvs_link_id, target, form_template_id, i_pathway, i_mail, i_print, i_favorite, last_modifier) VALUES ('9518259f77ec24884d1e172bd827596f', '07f0292ce90de23b787e3ad6be4c6770', 'Contact Us', '', 'caa046a2756e884ccddb396daecd3c12', '<div><span></span>\r\n<table style=\"width: 100%; border-collapse: collapse\" bordercolor=\"#000000\" cellspacing=\"0\" cellpadding=\"3\" align=\"center\" border=\"0\">\r\n<tbody>\r\n<tr valign=\"top\">\r\n<td width=\"10%\"></td>\r\n<td>\r\n<div>\r\n<div><span><font size=\"2\">Have questions or interested in contacting with us?</font></span></div>\r\n<div><span><font size=\"2\">&nbsp;</font></span></div>\r\n<div><span><font size=\"2\">HingePoint Consulting</font></span></div>\r\n<div><span><font size=\"2\">612-10 Carabob Ct</font></span></div>\r\n<div><span><font size=\"2\">Toronto, ON M1T 3N5</font></span></div>\r\n<div><span><font size=\"2\">Canada</font></span></div>\r\n<div><span><font size=\"3\"><br />\r\n</font><font size=\"2\">Tel:&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; +1-416-335-1610</font></span></div>\r\n<div><span><font size=\"2\">E-mail:&nbsp;&nbsp;</font><a href=\"&#109;&#97;&#105;&#108;&#116;&#111;&#58;&#105;&#110;&#102;&#111;&#64;&#104;&#105;&#110;&#103;&#101;&#112;&#111;&#105;&#110;&#116;&#99;&#111;&#110;&#115;&#117;&#108;&#116;&#105;&#110;&#103;&#46;&#99;&#111;&#109;\"><font size=\"2\">&#105;&#110;&#102;&#111;&#64;&#104;&#105;&#110;&#103;&#101;&#112;&#111;&#105;&#110;&#116;&#99;&#111;&#110;&#115;&#117;&#108;&#116;&#105;&#110;&#103;&#46;&#99;&#111;&#109;</font></a></span></div>\r\n<div><span></span><font size=\"2\"></font>&nbsp;</div>\r\n<div><font size=\"2\">&nbsp;</font></div>\r\n<div><font size=\"2\">Or simply fill out the following form.</font></div></div></td></tr>\r\n<tr valign=\"top\">\r\n<td width=\"10%\"></td>\r\n<td>\r\n<p align=\"left\"><span><span><img id=\"onlineform_13fbf54ecac119df2f43b310e7efc585\" style=\"width: 334px; height: 112px\" height=\"112\" alt=\"\" width=\"334\" border=\"1\" name=\"onlineform_13fbf54ecac119df2f43b310e7efc585\" src=\"/3rdparty/rvsitebuilder/themes/default/sitebuilder/images/layout_onlineform.jpg\" /></span></span></p>\r\n<div>&nbsp;</div></td></tr></tbody></table>&nbsp;</div>\r\n<div>&nbsp;&nbsp;</div>\r\n<div>\r\n<div><span><a href=\"&#109;&#97;&#105;&#108;&#116;&#111;&#58;&#105;&#110;&#102;&#111;&#64;&#104;&#105;&#110;&#103;&#101;&#112;&#111;&#105;&#110;&#116;&#99;&#111;&#110;&#115;&#117;&#108;&#116;&#105;&#110;&#103;&#46;&#99;&#111;&#109;\"><font size=\"3\"></font></a></span></div><span></span>&nbsp;</div>\r\n<div><span></span>&nbsp;</div>\r\n<div><span><span></span></span></div>\r\n<div>&nbsp;</div>\r\n<div>&nbsp;</div>', '', '', '', '', null, null, '', '', '', '18c1c0b915e0d1fd12d9c2db1ef4b661', null, null, null, null, '1258215211');
REPLACE INTO rvs_project_page (project_page_id, rvs_usr_id, page_name, custom_page_name, rvs_component_id, page_data, head, page_title, meta_keyword, meta_description, effect_page_enter, duration_page_enter, meta_page_effect, rvs_link_id, target, form_template_id, i_pathway, i_mail, i_print, i_favorite, last_modifier) VALUES ('f85aeca4bca6c2d70d0c8523a0227b52', '07f0292ce90de23b787e3ad6be4c6770', 'News & Events', '', '0', '<table class=\"rvFrame\" cellspacing=\"1\" cellpadding=\"1\" width=\"780\">\r\n<tbody>\r\n<tr>\r\n<td class=\"tdSolid\" valign=\"top\" align=\"left\" width=\"100%\"></td></tr></tbody></table>\r\n<p>New Website Lanuch</p>\r\n<p>Too better serve our clients, HingePoint lanuched the new webist on Nov 7, 2009. This website provides a new way to get to know HingePoint and the service it provides and communicate easily with the company.</p>\r\n<p>New Office!</p>\r\n<p>Hinge Point moves to the new office located in the heart of financial district of Toronto. With this new office, HingePoint will be more easily accessed by our clients. And the great facilities here will allow us to provice better service to our clients. </p>', '', '', '', '', null, null, '', '', '', '', null, null, null, null, '1258339554');
REPLACE INTO rvs_project_page (project_page_id, rvs_usr_id, page_name, custom_page_name, rvs_component_id, page_data, head, page_title, meta_keyword, meta_description, effect_page_enter, duration_page_enter, meta_page_effect, rvs_link_id, target, form_template_id, i_pathway, i_mail, i_print, i_favorite, last_modifier) VALUES ('45c48720839e97a5ae3a8050c099a6d4', '07f0292ce90de23b787e3ad6be4c6770', 'Company', '', '0', '<table id=\"rv_template_layout\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody>\r\n<tr>\r\n<td valign=\"top\" align=\"left\"></td></tr></tbody></table>\r\n<p>Located in Toronto, the economic center of Canada, HingePoint consulting provides corporate development, communications and client relations consulting service to all type of clients, from multibillion public companies to small capital start ups. HingePoint works closely with clients to help them to solve both strategic and operational business issues, communicate effectively and efficiently with their investors, business partners and customers, improve the performance of their organizations and create long lasting competitive advantages. </p>\r\n<p>Creative in problem solving, innovative in leading changes, HingePoint bring you not only feasible business strategies, but also tangible business results. </p>', '', '', '', '', null, null, '', '', '', '', null, null, null, null, '1258339371');
REPLACE INTO rvs_project_page (project_page_id, rvs_usr_id, page_name, custom_page_name, rvs_component_id, page_data, head, page_title, meta_keyword, meta_description, effect_page_enter, duration_page_enter, meta_page_effect, rvs_link_id, target, form_template_id, i_pathway, i_mail, i_print, i_favorite, last_modifier) VALUES ('9b8af15b52d70f0401a0e8768344ac89', '07f0292ce90de23b787e3ad6be4c6770', 'Management Team', '', '0', '<table id=\"rv_template_layout\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody>\r\n<tr>\r\n<td valign=\"top\" align=\"left\"></td></tr></tbody></table>\r\n<p>As a member of senior management teams for big corporations for years, Albert Yan has plenty of experience in the field of strategic planning, international cooperation, merger &amp; acquisition, business restructuring, marketing strategy, communications and customer relationship managements. He worked for multiple industries--automotive manufacturing, telecommunication service and management consulting. These experiences enable him to broad his vision beyond certain industries. </p>\r\n<p>With international working experience from China, Australia, United States and Canada and business trips to many more countries, Albert Yan has unique insights and hands on experience about cross board business partnership, whether it is a M&amp;A, joint venture, ownership interest or strategic alliance. </p>\r\n<p>Albert provided consulting service to all kinds of clients, from global 500 companies to small and medium enterprises in various industries. Being part of a multicultural group in Canada, Albert has profound understanding of multicultural groups, knows well about their needs, their thinking and their ways of doing business. </p>\r\n<p>Albert Yan holds a Master of Business Administration (MBA) degree from Georgetown University (Washington DC, U.S.A.), and a Master of Engineering degree and a Bachelor of Engineering degree from Xi&#8217;an Jiaotong University (Xi&#8217;an, P.R.C).</p>', '', '', '', '', null, null, '', '', '', '', null, null, null, null, '1258339725');
REPLACE INTO rvs_project_page (project_page_id, rvs_usr_id, page_name, custom_page_name, rvs_component_id, page_data, head, page_title, meta_keyword, meta_description, effect_page_enter, duration_page_enter, meta_page_effect, rvs_link_id, target, form_template_id, i_pathway, i_mail, i_print, i_favorite, last_modifier) VALUES ('15bf8f0baa322a42b0aca55d8b29fa02', '07f0292ce90de23b787e3ad6be4c6770', 'Communications', '', '0', '<table id=\"rv_template_layout\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody>\r\n<tr>\r\n<td valign=\"top\" align=\"left\"></td></tr></tbody></table>\r\n<p>To communicate effectively and efficiently with target clients can be challenging for some businesses, especially when they are facing multicultural clients. Don&#8217;t worry, HingePoint is here to help you.</p>\r\n<p>Language Translations Service</p>\r\n<p>English to and from Chinese, whether it is document translation or face to face interpreting service, HingePoint is more than happy to assist you.</p>\r\n<p>Event Planning </p>\r\n<p>Whether it is a trade show, or a special event, HingePoint is ready to help present your company to your customers, clients and interested stakeholders. </p>\r\n<p>Communication Materials </p>\r\n<p>Not sure your communication or marketing materials suit for some target business clients, prospective customers, or some special interest groups? HingePoint will tailor your communication materials to the specific needs of your targeted information receivers. </p>\r\n<p>Website Design and Multilingualization</p>\r\n<p>You have English website, but look into multicultural groups or overseas markets? You want your website has multiple language versions or at least get the key information out in the languages with which your customers feel comfortable. </p>', '', '', '', '', null, null, '', '', '', '', null, null, null, null, '1258339968');
REPLACE INTO rvs_project_page (project_page_id, rvs_usr_id, page_name, custom_page_name, rvs_component_id, page_data, head, page_title, meta_keyword, meta_description, effect_page_enter, duration_page_enter, meta_page_effect, rvs_link_id, target, form_template_id, i_pathway, i_mail, i_print, i_favorite, last_modifier) VALUES ('d73086fa3c4030f007cabaa982889a6b', '07f0292ce90de23b787e3ad6be4c6770', 'Client Relations', '', '0', '<table id=\"rv_template_layout\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody>\r\n<tr>\r\n<td valign=\"top\" align=\"left\"></td></tr></tbody></table>\r\n<p>How to develop, build up and keep a productive client relationship is crucial for the success of today&#8217;s businesses.</p>\r\n<p>Listen to and understand your target clients, care about what their needs are and what they are thinking, and knowing when, where and how to reach them are easier to say than done. Don&#8217;t worry, with the multicultural background, HingePoint is well positioned to help you to identify, find, reach and communicate with your clients and grow from there. </p>', '', '', '', '', null, null, '', '', '', '', null, null, null, null, '1258339839');
