REPLACE INTO rvs_layout_template (layout_template_id, layout_template_name, layout_template_data, layout_template_desc, layout_template_preview, layout_template_head, layout_group_id) VALUES ('5b7a994edd971a207ddb115a9855ef99', 'General style 12', '<!-- ####### LAYOUT CSS: MODIFY COLOR, FONT AND BOX SIZE HERE BUT DO NOT DELETE. ####### -->\r\n\r\n<style type=\"text/css\">\r\n\r\n.type12rightpad01{padding:10px 3px;}\r\n.type12rightpad02{padding:6px 3px;}\r\n.type12bgsilver{ background-color:#E7E7E7;}\r\n.type12bggray{ background-color:#C5C5C5;}\r\n.type12txtbold{ \r\n	font-weight:bold;\r\n}\r\n.type12txthead{ \r\n	font-weight:bold;\r\n	color:#535353;\r\n}\r\n.type12head{ font-weight:bold;}\r\n.type12linedash{border-bottom:#999999 dashed 1px;}\r\n.type12bgwhite{ \r\n	background-color:#FFFFFF;\r\n	color:#535353;\r\n}\r\n.type12txtbody{color:#535353;}\r\n</style>\r\n<!-- ########################### END CSS LAYOUT ###########################  -->\r\n<table cellpadding=\"0\" cellspacing=\"0\" id=\"rv_template_layout\">\r\n  <tr>\r\n  	<td align=\"left\" valign=\"top\">\r\n		<table cellpadding=\"5\" cellspacing=\"0\" width=\"100%\">\r\n			<tr>\r\n			  <td width=\"70%\" align=\"left\" valign=\"top\">\r\n			  	<table cellpadding=\"5\" cellspacing=\"0\" width=\"100%\" class=\"type12bgsilver\">\r\n					<tr>\r\n						<td valign=\"top\"><img src=\"images/180x60.gif\" alt=\"\" width=\"180\" height=\"60\" /></td>\r\n						<td valign=\"top\">\r\n							<div class=\"type12txthead\">Epsum factorial non deposit quid</div>\r\n							<div align=\"left\" class=\"type12txtbody\">Sic tempus fugit esperanto hiccup estrogen. Glorious baklava ex librus hup hey ad infinitum. Non sequitur condominium facile et geranium incognito. Epsum factorial non deposit quid pro quo hic escorol. </div></td>\r\n					</tr>\r\n				</table>\r\n				<br />\r\n				<table cellpadding=\"5\" cellspacing=\"0\" width=\"100%\" class=\"type12bgsilver\">\r\n					<tr>\r\n					  <td width=\"50%\" align=\"left\" valign=\"top